def compute(vars):
    revenue_2017 = vars["v1"]
    revenue_2018 = vars["v2"]
    total_revenue = revenue_2017 + revenue_2018
    return {
        "value": total_revenue,
        "trace": {
            "revenue_2017": revenue_2017,
            "revenue_2018": revenue_2018,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
